'use strict';

const { ExprError } = require('./errors');

/** CPython float modulo: fmod adjusted to the divisor's sign; zero is +0. */
function modulo(left, right) {
  let remainder = left % right;
  if (remainder === 0) return 0;
  if ((right < 0) !== (remainder < 0)) remainder += right;
  return remainder === 0 ? 0 : remainder;
}

/** CPython float floor division (via divmod), so results are correctly rounded; zero is +0. */
function floorDivide(left, right) {
  const remainder = left % right;
  let quotient = (left - remainder) / right;
  if (remainder !== 0 && (right < 0) !== (remainder < 0)) quotient -= 1;
  if (quotient === 0) return 0;
  let floored = Math.floor(quotient);
  if (quotient - floored > 0.5) floored += 1;
  return floored === 0 ? 0 : floored;
}

function apply(operator, left, right) {
  left = Number(left);
  right = Number(right);
  const value = operator.value;
  if ((value === '/' || value === '//' || value === '%') && right === 0) {
    throw new ExprError('Division by zero', operator.column);
  }
  switch (value) {
    case '+': return left + right;
    case '-': return left - right;
    case '*': return left * right;
    case '/': return left / right;
    case '**':
      // C99/Python pow: 1 ** y and (-1) ** ±inf are 1; JavaScript yields NaN.
      if (left === 1 || (left === -1 && Math.abs(right) === Infinity)) return 1;
      return left ** right;
    case '//': return floorDivide(left, right);
    case '%': return modulo(left, right);
    case '<': return left < right;
    case '<=': return left <= right;
    case '>': return left > right;
    case '>=': return left >= right;
    case '==': return left === right;
    case '!=': return left !== right;
    default: throw new Error('Invalid AST operator');
  }
}

/** Evaluate with explicit frames, so a long left-deep binary tree is safe. */
function evaluateAst(root, variables) {
  const frames = [{ node: root, phase: 0 }];
  let result;
  while (frames.length) {
    const frame = frames[frames.length - 1];
    const node = frame.node;
    if (node.type === 'number') {
      result = node.value;
      frames.pop();
    } else if (node.type === 'variable') {
      if (!Object.prototype.hasOwnProperty.call(variables, node.name)) {
        throw new ExprError('Unknown variable', node.column);
      }
      result = variables[node.name];
      frames.pop();
    } else if (node.type === 'unary') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.operand, phase: 0 });
      } else {
        result = node.operator.value === '-' ? -Number(result) : Number(result);
        frames.pop();
      }
    } else if (node.type === 'binary') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.left, phase: 0 });
      } else if (frame.phase === 1) {
        frame.left = result;
        frame.phase = 2;
        frames.push({ node: node.right, phase: 0 });
      } else {
        result = apply(node.operator, frame.left, result);
        frames.pop();
      }
    } else if (node.type === 'comparison') {
      if (frame.phase === 0) {
        frame.phase = 1;
        frames.push({ node: node.operands[0], phase: 0 });
      } else if (frame.phase === 1) {
        frame.left = result;
        frame.index = 0;
        frame.phase = 2;
        frames.push({ node: node.operands[1], phase: 0 });
      } else {
